/* ---------- 2. The small greyscale photo on each paired piece ---------- */
/** Post ID for a cocotran.com URL. url_to_postid() misses the magazine post types, so fall back to the slug. */
function ct_pair_post_id_from_url( $url ) {
	$pid = (int) url_to_postid( $url );
	if ( $pid ) { return $pid; }
	$path = trim( (string) parse_url( $url, PHP_URL_PATH ), '/' );
	if ( '' === $path ) { return 0; }
	$parts = explode( '/', $path );
	$slug  = sanitize_title( end( $parts ) );
	if ( '' === $slug ) { return 0; }
	$found = get_posts( array( 'name' => $slug, 'post_type' => array( 'property', 'guide', 'brief', 'dispatch', 'shortlist', 'post', 'page' ), 'post_status' => 'publish', 'posts_per_page' => 1, 'fields' => 'ids', 'no_found_rows' => true ) );
	if ( $found ) { return (int) $found[0]; }
	foreach ( array( 'property', 'guide', 'brief', 'dispatch', 'shortlist', 'post', 'page' ) as $pt ) { $o = get_page_by_path( $slug, OBJECT, $pt ); if ( $o instanceof WP_Post ) { return (int) $o->ID; } }
	return 0;
}
/** The photo for a piece: featured image, else the first image attached to it. */
function ct_pair_thumb_src( $pid ) {
	$src = get_the_post_thumbnail_url( $pid, 'medium' );
	if ( $src ) { return $src; }
	$media = get_attached_media( 'image', $pid );
	if ( $media ) { $first = reset( $media ); $src = wp_get_attachment_image_url( $first->ID, 'medium' ); if ( $src ) { return $src; } }
	return '';
}
function ct_pair_add_thumbs( $html ) {
	if ( ! is_string( $html ) || false === strpos( $html, 'class="ct-pair__link' ) || false !== strpos( $html, '<span class="ct-pair__thumb"' ) ) { return $html; } // the stylesheet also mentions ct-pair__thumb, so test for the markup, not the word
	return preg_replace_callback( '/<a class="ct-pair__link" href="([^"]+)">/', function ( $m ) {
		$pid = ct_pair_post_id_from_url( html_entity_decode( $m[1] ) );
		$src = $pid ? ct_pair_thumb_src( $pid ) : '';
		if ( ! $src ) { return $m[0]; }
		return '<a class="ct-pair__link has-thumb" href="' . $m[1] . '"><span class="ct-pair__thumb"><img src="' . esc_url( $src ) . '" alt="" loading="lazy" decoding="async"></span>';
	}, $html );
}
/* The plugin prints the blocks on different hooks depending on the template, so instead of guessing the hook the
   whole page passes through ct_pair_add_thumbs() once on output (singular pages only, idempotent, a few ms). */
add_action( 'template_redirect', function () {
	if ( is_admin() || ! is_singular() || is_feed() || ( defined( 'REST_REQUEST' ) && REST_REQUEST ) ) { return; }
	ob_start( 'ct_pair_add_thumbs' );
}, 1 );

/**
 * Code Snippets (WPCode) · PHP · Run everywhere.
 * On a Comparison brief the shared [ctt_book] box has no hotel of its own, so name the two
 * places from the piece's fields. Nothing else changes.
 */
add_filter( 'shortcode_atts_ctt_book', function ( $out ) {
	if ( ( $out['hotel'] ?? '' ) === '' && get_post_type() === 'brief' ) {
		$a = trim( (string) get_post_meta( get_the_ID(), 'side_a_name', true ) );
		$b = trim( (string) get_post_meta( get_the_ID(), 'side_b_name', true ) );
		if ( $a && $b ) { $out['hotel'] = $a . ' or ' . $b; }
	}
	return $out;
} );

/**
 * Code Snippets (WPCode) · PHP · Run everywhere.  v1.0 · 25 Oct 2026
 * Article schema for the magazine post types (property, guide, brief, dispatch, shortlist).
 * Rank Math emits no Article node on these (schema type "None"), so Google saw no author and no
 * modified date on them even though classic posts carry both. This adds one Article node per piece:
 * headline, author → the Person node the Site Snippets plugin already prints (@id /about/#person),
 * datePublished, dateModified (ACF `updated_on` when set, else the WordPress modified date), image,
 * description (Rank Math description, else the short answer). Classic posts are untouched.
 */
add_filter( 'rank_math/json_ld', function ( $data, $jsonld ) {
	if ( ! is_singular() || ! is_array( $data ) ) { return $data; }
	$post = get_queried_object();
	if ( ! $post instanceof WP_Post || ! in_array( $post->post_type, array( 'property', 'guide', 'brief', 'dispatch', 'shortlist' ), true ) ) { return $data; }
	$article_types = array( 'Article', 'NewsArticle', 'BlogPosting', 'TechArticle', 'Review', 'CreativeWork' );
	foreach ( $data as $entity ) {
		if ( is_array( $entity ) && ! empty( $entity['@type'] ) && array_intersect( (array) $entity['@type'], $article_types ) ) { return $data; } // Rank Math already has one
	}
	$url      = get_permalink( $post );
	$modified = function_exists( 'ct_updated_on_iso' ) ? ct_updated_on_iso( $post->ID ) : '';
	if ( '' === $modified ) { $modified = get_the_modified_date( 'c', $post ); }
	$desc = '';
	if ( class_exists( 'RankMath\\Helper' ) ) { $desc = (string) RankMath\Helper::get_post_meta( 'description', $post->ID ); }
	if ( '' === $desc ) { $desc = trim( wp_strip_all_tags( (string) get_post_meta( $post->ID, 'short_answer', true ) ) ); }
	if ( '' === $desc ) { $desc = trim( wp_strip_all_tags( (string) get_post_meta( $post->ID, 'comparison_short_answer', true ) ) ); }
	$person_id = function_exists( 'ct_person_id' ) ? ct_person_id() : home_url( '/about/#person' );
	$article = array(
		'@type'            => 'Article',
		'@id'              => $url . '#article',
		'headline'         => wp_strip_all_tags( get_the_title( $post ) ),
		'url'              => $url,
		'mainEntityOfPage' => $url,
		'datePublished'    => get_the_date( 'c', $post ),
		'dateModified'     => $modified,
		'author'           => array( '@id' => $person_id ),
		'publisher'        => array( '@type' => 'Organization', 'name' => get_bloginfo( 'name' ), 'url' => home_url( '/' ) ),
		'inLanguage'       => get_bloginfo( 'language' ),
	);
	if ( '' !== $desc ) { $article['description'] = $desc; }
	$img = get_the_post_thumbnail_url( $post, 'full' );
	if ( $img ) { $article['image'] = $img; }
	$data['ctArticle'] = $article;
	return $data;
}, 50, 2 ); // before the plugin's paywall/dateModified pass at 99, which then also stamps this node

/**
 * Code Snippets (WPCode) · PHP · Run everywhere.  v2.2 · 25 Oct 2026 (no PHP tags inside: WPCode strips them)
